		setAlignmentX(CENTER_ALIGNMENT);
		setVisible(false);
		addBottomPadding(10);
	}

	@Override
	public void updateVisibility()
	{
		Boolean visibleOpt = ComputeUtil.tryCompute(() ->
		{
			ComputeContext context = new ComputeContext();
