		);

		assertEquals(VoidLevel.NONE, voidLevelComputable.compute(context));
		assertEquals(VoidLevel.NONE, voidLevelComputable.compute(context));
		assertEquals(VoidLevel.NONE, voidLevelComputable.compute(context));
		assertEquals(VoidLevel.NONE, voidLevelComputable.compute(context));
