	void providesCorrectBonusesForMelee()
	{
		when(context.get(ComputeInputs.DEFENDER_ATTRIBUTES)).thenReturn(UNDEAD);
		when(context.get(ComputeInputs.ATTACK_STYLE)).thenReturn(ofAttackType(AttackType.STAB));
